import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { chmodSync, copyFileSync, existsSync, lstatSync, mkdtempSync, mkdirSync, readFileSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { dirname, isAbsolute, join, relative } from "node:path";
import { tmpdir } from "node:os";
import { createHash } from "node:crypto";
import {
  clearAllCredentials,
  formatOAuthCredentialStoreUnavailable,
  getAuthEntry,
  getAuthEntryFilePath,
  getAuthForUrl,
  getAuthStorageOptions,
  getTestAuthSecretStoreEntries,
  inspectAuthForUrl,
  OAuthCredentialStoreError,
  removeTestAuthSecretStoreEntry,
  resetAuthEntryCache,
  resetTestAuthSecretStore,
  saveAuthEntry,
  setTestAuthSecretStoreEntry,
} from "../mcp-auth.ts";

/**
 * Windows Credential Manager stores at most CRED_MAX_CREDENTIAL_BLOB_SIZE
 * (2560 bytes) as UTF-16, so a single value cannot exceed 1280 characters.
 */
const AUTH_SECRET_VALUE_LIMIT = 1280;
const AUTH_SECRET_CHUNK_SIZE = 1000;
const SERVER_URL = "https://example.com/mcp";

function accessTokenForSerializedLength(length: number): string {
  const envelopeLength = JSON.stringify({ tokens: { accessToken: "" }, serverUrl: SERVER_URL }).length;
  return "x".repeat(length - envelopeLength);
}

function accessTokenWithAstralCharacterAcrossNominalBoundary(): string {
  const marker = "TOKEN_MARKER";
  const serialized = JSON.stringify({ tokens: { accessToken: marker }, serverUrl: SERVER_URL });
  const tokenStart = serialized.indexOf(marker);
  return `${"x".repeat(AUTH_SECRET_CHUNK_SIZE - tokenStart - 1)}😀${"y".repeat(100)}`;
}

describe("OAuth credential-store diagnostics", () => {
  it("recognizes a revoked Linux keyring through the error cause chain", () => {
    const nativeError = new Error("Couldn't access platform storage: KeyRevoked", {
      cause: new Error("KeyRevoked"),
    });
    const error = new OAuthCredentialStoreError("read failed", "read", nativeError);

    const message = formatOAuthCredentialStoreUnavailable(error);
    if (process.platform === "linux") {
      expect(message).toContain("Linux session keyring may be revoked");
      expect(message).toContain("fresh login/keyring session");
    } else {
      expect(message).toContain("OAuth credential store unavailable");
    }
  });

  it("explains Windows network-logon error 1312 without falling back", () => {
    const error = new OAuthCredentialStoreError("write failed", "write", new Error("ERROR_NO_SUCH_LOGON_SESSION (1312)"));
    expect(formatOAuthCredentialStoreUnavailable(error)).toContain("Windows Credential Manager is unavailable from this network logon");
    expect(formatOAuthCredentialStoreUnavailable(error)).toContain('oauthCredentialStore to "encrypted-file"');
  });

  it("does not infer the encrypted backend from untrusted OS error text", () => {
    const error = new OAuthCredentialStoreError(
      "Failed for server encrypted OAuth credential file store",
      "read",
      new Error("encrypted OAuth credential file store PI_MCP_ADAPTER_OAUTH_FILE_KEY"),
    );
    const message = formatOAuthCredentialStoreUnavailable(error);
    expect(message).toContain("Configure or unlock the OS credential store");
    expect(message).not.toContain("Encrypted OAuth credential file store unavailable");
  });
});

describe("encrypted OAuth credential file store", () => {
  const key = Buffer.alloc(32, 7).toString("base64");
  const rotatedKey = Buffer.alloc(32, 8).toString("base64");
  const originalEnv = {
    PI_CODING_AGENT_DIR: process.env.PI_CODING_AGENT_DIR,
    PI_MCP_ADAPTER_OAUTH_FILE_KEY: process.env.PI_MCP_ADAPTER_OAUTH_FILE_KEY,
    PI_MCP_ADAPTER_TEST_AUTH_STORE: process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE,
    PI_MCP_ADAPTER_DISABLE_AUTH_CACHE: process.env.PI_MCP_ADAPTER_DISABLE_AUTH_CACHE,
  };
  let agentDir: string;
  let options: ReturnType<typeof getAuthStorageOptions>;

  beforeEach(() => {
    agentDir = mkdtempSync(join(tmpdir(), "pi-mcp-encrypted-auth-"));
    process.env.PI_CODING_AGENT_DIR = agentDir;
    process.env.PI_MCP_ADAPTER_OAUTH_FILE_KEY = key;
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "unavailable";
    options = getAuthStorageOptions(undefined, process.cwd(), "encrypted-file");
    resetTestAuthSecretStore();
  });

  afterEach(() => {
    for (const [name, value] of Object.entries(originalEnv)) {
      if (value === undefined) delete process.env[name];
      else process.env[name] = value;
    }
    rmSync(agentDir, { recursive: true, force: true });
  });

  function credentialPath(serverName: string): string {
    const account = `sha256-${createHash("sha256").update(serverName).digest("hex")}`;
    return join(agentDir, "mcp-oauth-encrypted", account, "credentials.json");
  }

  it("selects only the explicit backend and ignores legacy path configuration", () => {
    expect(getAuthStorageOptions(undefined, process.cwd())).toEqual({});
    expect(getAuthStorageOptions(123, process.cwd(), "encrypted-file")).toEqual({ credentialStore: "encrypted-file" });
    expect(() => getAuthStorageOptions(undefined, process.cwd(), "plaintext")).toThrow(/oauthCredentialStore/);
  });

  it("round-trips and removes credentials without persisting secrets", () => {
    const entry = {
      tokens: { accessToken: "access-secret", refreshToken: "refresh-secret" },
      clientInfo: { clientId: "client", clientSecret: "client-secret" },
      codeVerifier: "verifier-secret",
      oauthState: "state-secret",
    };
    saveAuthEntry("secure-server", entry, SERVER_URL, options);
    const path = credentialPath("secure-server");
    const persisted = readFileSync(path, "utf8");
    for (const secret of ["access-secret", "refresh-secret", "client-secret", "verifier-secret", "state-secret", SERVER_URL]) {
      expect(persisted).not.toContain(secret);
    }
    resetAuthEntryCache();
    expect(getAuthEntry("secure-server", options)).toEqual({ ...entry, serverUrl: SERVER_URL });
    clearAllCredentials("secure-server", options);
    expect(existsSync(path)).toBe(false);
  });

  it("uses fresh ciphertext when credentials are rewritten", () => {
    saveAuthEntry("rewrite", { tokens: { accessToken: "secret" } }, SERVER_URL, options);
    const first = readFileSync(credentialPath("rewrite"), "utf8");
    saveAuthEntry("rewrite", { tokens: { accessToken: "secret" } }, SERVER_URL, options);
    expect(readFileSync(credentialPath("rewrite"), "utf8")).not.toBe(first);
  });

  it("rejects missing and malformed keys", () => {
    for (const badKey of [undefined, "not-base64", Buffer.alloc(31).toString("base64"), `${key}\n`]) {
      if (badKey === undefined) delete process.env.PI_MCP_ADAPTER_OAUTH_FILE_KEY;
      else process.env.PI_MCP_ADAPTER_OAUTH_FILE_KEY = badKey;
      expect(() => getAuthEntry("key-validation", options)).toThrow(OAuthCredentialStoreError);
      const status = inspectAuthForUrl("key-validation", SERVER_URL, options);
      expect(status.status).toBe("unavailable");
      if (badKey === undefined && status.status === "unavailable") {
        expect(status.message).toContain("PI_MCP_ADAPTER_OAUTH_FILE_KEY");
        expect(status.message).not.toContain("OS credential store");
      }
    }
  });

  it("does not serve cached credentials after the key changes or disappears", () => {
    saveAuthEntry("key-rotation", { tokens: { accessToken: "secret" } }, SERVER_URL, options);
    expect(getAuthEntry("key-rotation", options)?.tokens?.accessToken).toBe("secret");
    process.env.PI_MCP_ADAPTER_OAUTH_FILE_KEY = rotatedKey;
    expect(() => getAuthEntry("key-rotation", options)).toThrow(OAuthCredentialStoreError);
    delete process.env.PI_MCP_ADAPTER_OAUTH_FILE_KEY;
    expect(inspectAuthForUrl("key-rotation", SERVER_URL, options).status).toBe("unavailable");
  });

  it("evicts every cached key generation after removal", () => {
    delete process.env.PI_MCP_ADAPTER_DISABLE_AUTH_CACHE;
    saveAuthEntry("remove-generations", { tokens: { accessToken: "secret" } }, SERVER_URL, options);
    expect(getAuthEntry("remove-generations", options)?.tokens?.accessToken).toBe("secret");

    process.env.PI_MCP_ADAPTER_OAUTH_FILE_KEY = rotatedKey;
    clearAllCredentials("remove-generations", options);
    expect(existsSync(credentialPath("remove-generations"))).toBe(false);

    process.env.PI_MCP_ADAPTER_OAUTH_FILE_KEY = key;
    expect(getAuthEntry("remove-generations", options)).toBeUndefined();
  });

  it("does not evict a different NUL-containing server name", () => {
    delete process.env.PI_MCP_ADAPTER_DISABLE_AUTH_CACHE;
    const cachedServer = "x\0bar";
    saveAuthEntry(cachedServer, { tokens: { accessToken: "cached-secret" } }, SERVER_URL, options);
    expect(getAuthEntry(cachedServer, options)?.tokens?.accessToken).toBe("cached-secret");
    rmSync(dirname(credentialPath(cachedServer)), { recursive: true });
    expect(existsSync(credentialPath(cachedServer))).toBe(false);

    process.env.PI_MCP_ADAPTER_OAUTH_FILE_KEY = rotatedKey;
    clearAllCredentials("bar", options);

    process.env.PI_MCP_ADAPTER_OAUTH_FILE_KEY = key;
    expect(getAuthEntry(cachedServer, options)?.tokens?.accessToken).toBe("cached-secret");
  });

  it("rejects tampered ciphertext", () => {
    saveAuthEntry("tamper", { tokens: { accessToken: "secret" } }, SERVER_URL, options);
    const path = credentialPath("tamper");
    const envelope = JSON.parse(readFileSync(path, "utf8")) as { ciphertext: string };
    envelope.ciphertext = `${envelope.ciphertext[0] === "A" ? "B" : "A"}${envelope.ciphertext.slice(1)}`;
    writeFileSync(path, JSON.stringify(envelope), { mode: 0o600 });
    const status = inspectAuthForUrl("tamper", SERVER_URL, options);
    expect(status).toMatchObject({ status: "unavailable" });
    if (status.status === "unavailable") {
      expect(status.message).toContain("encrypted credential file and key");
      expect(status.message).toContain("reauthenticate");
      expect(status.message).not.toContain("OS credential store");
    }
    expect(getTestAuthSecretStoreEntries()).toEqual([]);
  });

  it("binds ciphertext to its server account", () => {
    saveAuthEntry("account-a", { tokens: { accessToken: "secret" } }, SERVER_URL, options);
    const copied = credentialPath("account-b");
    mkdirSync(dirname(copied), { recursive: true, mode: 0o700 });
    copyFileSync(credentialPath("account-a"), copied);
    chmodSync(copied, 0o600);
    expect(inspectAuthForUrl("account-b", SERVER_URL, options).status).toBe("unavailable");
  });

  it("preserves URL binding", () => {
    saveAuthEntry("url-bound", { tokens: { accessToken: "secret" } }, SERVER_URL, options);
    expect(getAuthForUrl("url-bound", SERVER_URL, options)?.tokens?.accessToken).toBe("secret");
    expect(getAuthForUrl("url-bound", "https://other.example/mcp", options)).toBeUndefined();
  });

  it("leaves legacy plaintext untouched", () => {
    const legacyPath = getAuthEntryFilePath("legacy", { baseDir: join(agentDir, "legacy") });
    mkdirSync(dirname(legacyPath), { recursive: true });
    writeFileSync(legacyPath, JSON.stringify({ tokens: { accessToken: "legacy" }, serverUrl: SERVER_URL }));
    expect(getAuthEntry("legacy", options)).toBeUndefined();
    expect(existsSync(legacyPath)).toBe(true);
  });

  it.runIf(process.platform !== "win32")("creates private files and rejects permissive files", () => {
    saveAuthEntry("permissions", { tokens: { accessToken: "secret" } }, SERVER_URL, options);
    const path = credentialPath("permissions");
    expect(lstatSync(path).mode & 0o777).toBe(0o600);
    chmodSync(path, 0o644);
    resetAuthEntryCache();
    expect(() => getAuthEntry("permissions", options)).toThrow(OAuthCredentialStoreError);
  });

  it.runIf(process.platform !== "win32")("rejects regular and dangling symlink destinations for every operation", () => {
    const target = join(agentDir, "target.json");
    writeFileSync(target, "{}", { mode: 0o600 });
    const symlinkPath = credentialPath("symlink");
    mkdirSync(dirname(symlinkPath), { recursive: true });
    symlinkSync(target, symlinkPath);
    expect(() => getAuthEntry("symlink", options)).toThrow(OAuthCredentialStoreError);

    for (const operation of ["read", "remove", "write"] as const) {
      const server = `dangling-${operation}`;
      const path = credentialPath(server);
      mkdirSync(dirname(path), { recursive: true });
      symlinkSync(join(agentDir, "missing-target"), path);
      if (operation === "read") expect(() => getAuthEntry(server, options)).toThrow(OAuthCredentialStoreError);
      if (operation === "remove") expect(() => clearAllCredentials(server, options)).toThrow(OAuthCredentialStoreError);
      if (operation === "write") expect(() => saveAuthEntry(server, { tokens: { accessToken: "secret" } }, SERVER_URL, options)).toThrow(OAuthCredentialStoreError);
      expect(lstatSync(path).isSymbolicLink()).toBe(true);
    }
  });
});

describe("mcp-auth storage paths", () => {
  const originalEnv = {
    MCP_OAUTH_DIR: process.env.MCP_OAUTH_DIR,
    PI_MCP_ADAPTER_TEST_AUTH_STORE: process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE,
    PI_MCP_ADAPTER_TEST_LINUX_KEYRING_RECOVERY: process.env.PI_MCP_ADAPTER_TEST_LINUX_KEYRING_RECOVERY,
    PI_MCP_ADAPTER_KEYRING_RECOVERY_KEYCTL: process.env.PI_MCP_ADAPTER_KEYRING_RECOVERY_KEYCTL,
    PI_MCP_ADAPTER_KEYRING_RECOVERY_NODE: process.env.PI_MCP_ADAPTER_KEYRING_RECOVERY_NODE,
    PI_MCP_ADAPTER_KEYRING_RECOVERY_HELPER: process.env.PI_MCP_ADAPTER_KEYRING_RECOVERY_HELPER,
    PI_MCP_ADAPTER_FAKE_KEYRING_STORE: process.env.PI_MCP_ADAPTER_FAKE_KEYRING_STORE,
  };
  let authDir: string;

  beforeEach(() => {
    authDir = mkdtempSync(join(tmpdir(), "pi-mcp-auth-storage-"));
    process.env.MCP_OAUTH_DIR = authDir;
    resetTestAuthSecretStore();
  });

  afterEach(() => {
    for (const [key, value] of Object.entries(originalEnv)) {
      if (value === undefined) {
        delete process.env[key];
      } else {
        process.env[key] = value;
      }
    }
    rmSync(authDir, { recursive: true, force: true });
  });

  it("keeps arbitrary configured server names under safe hashed legacy import paths", () => {
    const names = ["Cloudflare Workers", "сервер", "../escape", "@scope/name", ""];

    for (const [index, name] of names.entries()) {
      const token = `token-${index}`;
      saveAuthEntry(name, { tokens: { accessToken: token } }, "https://example.com/mcp");

      expect(getAuthEntry(name)?.tokens?.accessToken).toBe(token);
      const filePath = getAuthEntryFilePath(name);
      const rel = relative(authDir, filePath);
      expect(rel.startsWith("..")).toBe(false);
      expect(isAbsolute(rel)).toBe(false);
      expect(rel).toMatch(/^sha256-[a-f0-9]{64}\/tokens\.json$/);
      expect(existsSync(filePath)).toBe(false);
    }

    expect(existsSync(join(authDir, "..", "escape", "tokens.json"))).toBe(false);
  });

  it("rejects non-string names at the storage boundary", () => {
    expect(() => getAuthEntryFilePath(undefined as unknown as string)).toThrow(/Invalid MCP server name/);
  });

  it("uses configured oauthDir as the legacy import source", () => {
    delete process.env.MCP_OAUTH_DIR;
    const project = mkdtempSync(join(tmpdir(), "pi-mcp-auth-project-"));
    const options = getAuthStorageOptions(".pi/oauth", project);
    const filePath = getAuthEntryFilePath("configured", options);
    mkdirSync(dirname(filePath), { recursive: true });
    writeFileSync(filePath, JSON.stringify({ tokens: { accessToken: "legacy-token" }, serverUrl: "https://example.com/mcp" }), "utf-8");

    expect(getAuthEntry("configured", options)?.tokens?.accessToken).toBe("legacy-token");
    expect(filePath.startsWith(join(project, ".pi", "oauth"))).toBe(true);
    expect(existsSync(filePath)).toBe(false);
    expect(getAuthEntry("configured", options)?.tokens?.accessToken).toBe("legacy-token");
    rmSync(project, { recursive: true, force: true });
  });

  it("does not migrate legacy credentials during status-only inspection", () => {
    const filePath = getAuthEntryFilePath("status-only");
    mkdirSync(dirname(filePath), { recursive: true });
    writeFileSync(filePath, JSON.stringify({
      tokens: { accessToken: "legacy-token" },
      serverUrl: "https://example.com/mcp",
    }), "utf-8");

    expect(inspectAuthForUrl("status-only", "https://example.com/mcp").status).toBe("present");
    expect(existsSync(filePath)).toBe(true);

    expect(getAuthEntry("status-only")?.tokens?.accessToken).toBe("legacy-token");
    expect(existsSync(filePath)).toBe(false);
  });

  it("does not use configured oauthDir values as secure-store namespaces", () => {
    delete process.env.MCP_OAUTH_DIR;
    const projectA = mkdtempSync(join(tmpdir(), "pi-mcp-auth-project-a-"));
    const projectB = mkdtempSync(join(tmpdir(), "pi-mcp-auth-project-b-"));
    const optionsA = getAuthStorageOptions(".pi/oauth", projectA);
    const optionsB = getAuthStorageOptions(".pi/oauth", projectB);

    saveAuthEntry("same-server", { tokens: { accessToken: "token-a" } }, "https://example.com/mcp", optionsA);
    saveAuthEntry("same-server", { tokens: { accessToken: "token-b" } }, "https://example.com/mcp", optionsB);

    expect(getAuthEntry("same-server", optionsA)?.tokens?.accessToken).toBe("token-b");
    expect(getAuthEntry("same-server", optionsB)?.tokens?.accessToken).toBe("token-b");
    rmSync(projectA, { recursive: true, force: true });
    rmSync(projectB, { recursive: true, force: true });
  });

  it("keeps MCP_OAUTH_DIR as the explicit override over settings.oauthDir", () => {
    const project = mkdtempSync(join(tmpdir(), "pi-mcp-auth-project-"));
    const options = getAuthStorageOptions(".pi/oauth", project);

    saveAuthEntry("env-override", { tokens: { accessToken: "token" } }, "https://example.com/mcp", options);

    const filePath = getAuthEntryFilePath("env-override", options);
    expect(filePath.startsWith(authDir)).toBe(true);
    expect(filePath.startsWith(join(project, ".pi", "oauth"))).toBe(false);
    rmSync(project, { recursive: true, force: true });
  });

  it("stores an ordinary 9 KiB payload as one native item outside Windows", () => {
    const accessToken = accessTokenForSerializedLength(9 * 1024);
    saveAuthEntry("large-entry", { tokens: { accessToken } }, SERVER_URL);

    expect(getAuthEntry("large-entry")?.tokens?.accessToken).toBe(accessToken);
    const entries = getTestAuthSecretStoreEntries();
    if (process.platform === "win32") {
      const manifestEntry = entries.find(([account]) => !account.includes(".chunk."));
      const chunkEntries = entries.filter(([account]) => account.includes(".chunk."));
      expect(manifestEntry).toBeDefined();
      const manifest = JSON.parse(manifestEntry![1]) as { __piMcpAdapterOAuthChunked?: number; chunkCount?: number };
      expect(manifest.__piMcpAdapterOAuthChunked).toBe(1);
      expect(chunkEntries).toHaveLength(manifest.chunkCount!);
      expect(chunkEntries.every(([, payload]) => payload.length <= AUTH_SECRET_VALUE_LIMIT)).toBe(true);
    } else {
      expect(entries).toHaveLength(1);
      expect(entries[0][0]).not.toContain(".chunk.");
      expect(JSON.parse(entries[0][1]).__piMcpAdapterOAuthChunked).toBeUndefined();
    }
  });

  it("uses the serialized 1000-character boundary for the size-limited store", () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";

    for (const [serverName, payloadLength, chunked] of [
      ["size-limited-at-boundary", AUTH_SECRET_CHUNK_SIZE, false],
      ["size-limited-over-boundary", AUTH_SECRET_CHUNK_SIZE + 1, true],
    ] as const) {
      resetTestAuthSecretStore();
      const accessToken = accessTokenForSerializedLength(payloadLength);
      saveAuthEntry(serverName, { tokens: { accessToken } }, SERVER_URL);

      expect(getAuthEntry(serverName)?.tokens?.accessToken).toBe(accessToken);
      const entries = getTestAuthSecretStoreEntries();
      expect(entries.every(([, payload]) => payload.length <= AUTH_SECRET_VALUE_LIMIT)).toBe(true);
      expect(entries.some(([account]) => account.includes(".chunk."))).toBe(chunked);
      const primary = entries.find(([account]) => !account.includes(".chunk."));
      expect(primary).toBeDefined();
      expect(JSON.parse(primary![1]).__piMcpAdapterOAuthChunked === 1).toBe(chunked);
    }
  });

  it("keeps surrogate pairs intact across native-string chunk round trips", () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";
    const accessToken = accessTokenWithAstralCharacterAcrossNominalBoundary();
    const serialized = JSON.stringify({ tokens: { accessToken }, serverUrl: SERVER_URL });
    expect([serialized.charCodeAt(999), serialized.charCodeAt(1000)]).toEqual([0xd83d, 0xde00]);
    saveAuthEntry("unicode-boundary", { tokens: { accessToken } }, SERVER_URL);

    const chunkEntries = getTestAuthSecretStoreEntries().filter(([account]) => account.includes(".chunk."));
    expect(chunkEntries.length).toBeGreaterThan(1);
    expect(chunkEntries.every(([, payload]) => payload.length <= AUTH_SECRET_CHUNK_SIZE)).toBe(true);
    for (const [account, payload] of chunkEntries) {
      const nativeRoundTrip = Buffer.from(payload, "utf8").toString("utf8");
      expect(nativeRoundTrip).not.toContain("�");
      setTestAuthSecretStoreEntry(account, nativeRoundTrip);
    }

    resetAuthEntryCache();
    expect(getAuthEntry("unicode-boundary")?.tokens?.accessToken).toBe(accessToken);
  });

  it("persists records that exceed the strictest per-value store limit", () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";
    const accessToken = "x".repeat(5000);

    saveAuthEntry("size-limited-large", { tokens: { accessToken } }, "https://example.com/mcp");

    expect(getAuthEntry("size-limited-large")?.tokens?.accessToken).toBe(accessToken);
    expect(getTestAuthSecretStoreEntries().every(([, payload]) => payload.length <= AUTH_SECRET_VALUE_LIMIT)).toBe(true);
  });

  it("persists records just above the per-value limit that are too small for a naive chunk threshold", () => {
    // Regression: a threshold above the store limit skipped chunking entirely,
    // so records in this band failed to persist on Windows at any payload size.
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";
    const accessToken = "x".repeat(AUTH_SECRET_VALUE_LIMIT + 200);

    saveAuthEntry("size-limited-boundary", { tokens: { accessToken } }, "https://example.com/mcp");

    expect(getAuthEntry("size-limited-boundary")?.tokens?.accessToken).toBe(accessToken);
    expect(getTestAuthSecretStoreEntries().every(([, payload]) => payload.length <= AUTH_SECRET_VALUE_LIMIT)).toBe(true);
  });

  it("keeps small records in a single entry on a size-limited store", () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";

    saveAuthEntry("size-limited-small", { tokens: { accessToken: "small" } }, "https://example.com/mcp");

    expect(getAuthEntry("size-limited-small")?.tokens?.accessToken).toBe("small");
    const entries = getTestAuthSecretStoreEntries();
    expect(entries).toHaveLength(1);
    expect(entries[0][0]).not.toContain(".chunk.");
  });

  it("clears chunked records written to a size-limited store", () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";
    saveAuthEntry("size-limited-remove", { tokens: { accessToken: "x".repeat(5000) } }, "https://example.com/mcp");
    expect(getTestAuthSecretStoreEntries().some(([account]) => account.includes(".chunk."))).toBe(true);

    clearAllCredentials("size-limited-remove");

    expect(getTestAuthSecretStoreEntries()).toHaveLength(0);
  });

  it("returns unavailable status when a stored chunk cannot be read", () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";
    saveAuthEntry("large-status", { tokens: { accessToken: "x".repeat(5000) } }, "https://example.com/mcp");
    const chunkAccount = getTestAuthSecretStoreEntries().find(([account]) => account.includes(".chunk."))?.[0];
    expect(chunkAccount).toBeDefined();
    removeTestAuthSecretStoreEntry(chunkAccount!);

    expect(inspectAuthForUrl("large-status", "https://example.com/mcp").status).toBe("unavailable");
  });

  it("rejects schema-valid chunk corruption without compacting or deleting it", () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";
    saveAuthEntry("corrupt-chunk", { tokens: { accessToken: "x".repeat(5000) } }, SERVER_URL);
    const [chunkAccount, chunkPayload] = getTestAuthSecretStoreEntries()
      .find(([account, payload]) => account.includes(".chunk.") && payload.includes("x"))!;
    setTestAuthSecretStoreEntry(chunkAccount, chunkPayload.replace("x", "y"));
    const corruptedEntries = getTestAuthSecretStoreEntries();

    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "memory";
    resetAuthEntryCache();
    expect(inspectAuthForUrl("corrupt-chunk", SERVER_URL).status).toBe("unavailable");
    expect(getTestAuthSecretStoreEntries()).toEqual(corruptedEntries);
    expect(() => getAuthEntry("corrupt-chunk")).toThrow(/read OAuth credentials/);
    expect(getTestAuthSecretStoreEntries()).toEqual(corruptedEntries);
  });

  it("removes chunk payloads when credentials are cleared", () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";
    saveAuthEntry("large-remove", { tokens: { accessToken: "x".repeat(5000) } }, "https://example.com/mcp");
    const storedAccounts = getTestAuthSecretStoreEntries().map(([account]) => account);
    expect(storedAccounts.some(account => account.includes(".chunk."))).toBe(true);

    clearAllCredentials("large-remove");

    const remainingAccounts = new Set(getTestAuthSecretStoreEntries().map(([account]) => account));
    expect(storedAccounts.every(account => !remainingAccounts.has(account))).toBe(true);
  });

  it("cleans stale chunks when a large entry is replaced by a small one", () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";
    saveAuthEntry("large-to-small", { tokens: { accessToken: "x".repeat(5000) } }, "https://example.com/mcp");
    expect(getTestAuthSecretStoreEntries().some(([account]) => account.includes(".chunk."))).toBe(true);

    saveAuthEntry("large-to-small", { tokens: { accessToken: "small" } }, "https://example.com/mcp");

    expect(getAuthEntry("large-to-small")?.tokens?.accessToken).toBe("small");
    const entries = getTestAuthSecretStoreEntries();
    expect(entries).toHaveLength(1);
    expect(entries[0][0]).not.toContain(".chunk.");
  });

  it("does not compact chunked records during status-only inspection", () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";
    const accessToken = "x".repeat(5000);
    saveAuthEntry("status-chunks", { tokens: { accessToken } }, "https://example.com/mcp");
    const before = getTestAuthSecretStoreEntries().length;
    expect(before).toBeGreaterThan(1);

    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "memory";
    resetAuthEntryCache();
    expect(inspectAuthForUrl("status-chunks", "https://example.com/mcp").status).toBe("present");
    expect(getTestAuthSecretStoreEntries().some(([account]) => account.includes(".chunk."))).toBe(true);
    expect(getTestAuthSecretStoreEntries()).toHaveLength(before);

    expect(getAuthEntry("status-chunks")?.tokens?.accessToken).toBe(accessToken);
    const compacted = getTestAuthSecretStoreEntries();
    expect(compacted).toHaveLength(1);
    expect(compacted[0][0]).not.toContain(".chunk.");
  });

  it("preserves readable chunks and reports a failed primary compaction write", () => {
    if (process.platform === "win32") return;
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "sizelimited";
    const accessToken = "x".repeat(5000);
    saveAuthEntry("failed-compaction", { tokens: { accessToken } }, SERVER_URL);
    const before = getTestAuthSecretStoreEntries();

    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "writefailing";
    resetAuthEntryCache();
    expect(() => getAuthEntry("failed-compaction")).toThrow(/write OAuth credentials/);
    expect(getTestAuthSecretStoreEntries()).toEqual(before);
    expect(inspectAuthForUrl("failed-compaction", SERVER_URL).status).toBe("present");
  });

  it("routes revoked Linux keyring operations through the recovery helper", () => {
    const harnessDir = mkdtempSync(join(tmpdir(), "pi-mcp-keyring-recovery-"));
    const keyctlPath = join(harnessDir, "keyctl");
    const helperPath = join(harnessDir, "helper.cjs");
    const storePath = join(harnessDir, "store.json");

    writeFileSync(keyctlPath, `#!/usr/bin/env bash
set -euo pipefail
if [ "$1" != "session" ] || [ "$2" != "-" ]; then exit 64; fi
shift 2
exec "$@"
`, { mode: 0o755 });
    writeFileSync(helperPath, `const { existsSync, readFileSync, writeFileSync } = require('node:fs');
const input = JSON.parse(readFileSync(0, 'utf8'));
const path = process.env.PI_MCP_ADAPTER_FAKE_KEYRING_STORE;
const store = existsSync(path) ? JSON.parse(readFileSync(path, 'utf8')) : {};
if (input.operation === 'read') {
  const value = store[input.account];
  process.stdout.write(JSON.stringify(value === undefined ? { ok: true, found: false } : { ok: true, found: true, value }) + '\\n');
} else if (input.operation === 'write') {
  store[input.account] = input.payload;
  writeFileSync(path, JSON.stringify(store));
  process.stdout.write(JSON.stringify({ ok: true }) + '\\n');
} else if (input.operation === 'remove') {
  delete store[input.account];
  writeFileSync(path, JSON.stringify(store));
  process.stdout.write(JSON.stringify({ ok: true }) + '\\n');
} else {
  process.stdout.write(JSON.stringify({ ok: false, error: 'bad op' }) + '\\n');
  process.exitCode = 1;
}
`);

    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "keyrevoked";
    process.env.PI_MCP_ADAPTER_TEST_LINUX_KEYRING_RECOVERY = "1";
    process.env.PI_MCP_ADAPTER_KEYRING_RECOVERY_KEYCTL = keyctlPath;
    process.env.PI_MCP_ADAPTER_KEYRING_RECOVERY_NODE = process.execPath;
    process.env.PI_MCP_ADAPTER_KEYRING_RECOVERY_HELPER = helperPath;
    process.env.PI_MCP_ADAPTER_FAKE_KEYRING_STORE = storePath;

    const accessToken = "x".repeat(5000);
    saveAuthEntry("recovered", { tokens: { accessToken } }, "https://example.com/mcp");

    expect(getAuthEntry("recovered")?.tokens?.accessToken).toBe(accessToken);

    clearAllCredentials("recovered");

    expect(getAuthEntry("recovered")).toBeUndefined();
    expect(JSON.parse(readFileSync(storePath, "utf8"))).toEqual({});
    rmSync(harnessDir, { recursive: true, force: true });
  });

  it("does not use the recovery helper for generic secure-store failures", () => {
    const harnessDir = mkdtempSync(join(tmpdir(), "pi-mcp-keyring-no-recovery-"));
    const keyctlPath = join(harnessDir, "keyctl");
    const storePath = join(harnessDir, "store.json");
    writeFileSync(keyctlPath, "#!/usr/bin/env bash\nexit 99\n", { mode: 0o755 });

    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "unavailable";
    process.env.PI_MCP_ADAPTER_TEST_LINUX_KEYRING_RECOVERY = "1";
    process.env.PI_MCP_ADAPTER_KEYRING_RECOVERY_KEYCTL = keyctlPath;
    process.env.PI_MCP_ADAPTER_FAKE_KEYRING_STORE = storePath;

    expect(() => getAuthEntry("generic-unavailable")).toThrow(/OS secure credential store/);
    expect(existsSync(storePath)).toBe(false);
    rmSync(harnessDir, { recursive: true, force: true });
  });
});

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { mkdtempSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import {
  type AuthEntry,
  getAuthEntry,
  getTestAuthSecretStoreEntries,
  getTestAuthSecretStoreReadCount,
  inspectAuthForUrl,
  invalidateAuthEntryCache,
  removeAuthEntry,
  resetAuthEntryCache,
  resetTestAuthSecretStore,
  saveAuthEntry,
  updateTokens,
} from "../mcp-auth.ts";

const STORE_ENV = "PI_MCP_ADAPTER_TEST_AUTH_STORE";
const DISABLE_ENV = "PI_MCP_ADAPTER_DISABLE_AUTH_CACHE";
const RECOVERY_OVERRIDE_ENV = "PI_MCP_ADAPTER_TEST_LINUX_KEYRING_RECOVERY";
const DISABLE_KEYRING_RECOVERY_ENV = "PI_MCP_ADAPTER_DISABLE_KEYRING_RECOVERY";
const SERVER_URL = "https://example.com/mcp";

function enableAuthEntryCache(): void {
  delete process.env[DISABLE_ENV];
}

function useAuthCacheHarness(): void {
  const originalEnv: Record<string, string | undefined> = {
    MCP_OAUTH_DIR: process.env.MCP_OAUTH_DIR,
    [STORE_ENV]: process.env[STORE_ENV],
    [DISABLE_ENV]: process.env[DISABLE_ENV],
    [DISABLE_KEYRING_RECOVERY_ENV]: process.env[DISABLE_KEYRING_RECOVERY_ENV],
  };
  let authDir: string;

  beforeEach(() => {
    authDir = mkdtempSync(join(tmpdir(), "pi-mcp-auth-cache-"));
    process.env.MCP_OAUTH_DIR = authDir;
    resetTestAuthSecretStore();
  });

  afterEach(() => {
    for (const [key, value] of Object.entries(originalEnv)) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
    rmSync(authDir, { recursive: true, force: true });
  });
}

describe("OAuth credential-entry cache — foundation", () => {
  useAuthCacheHarness();

  it("disables the cache suite-wide by default", () => {
    expect(process.env[DISABLE_ENV]).toBe("1");
  });

  it("counts reads and resets independently for memory and size-limited stores", () => {
    for (const store of ["memory", "sizelimited"]) {
      process.env[STORE_ENV] = store;
      resetTestAuthSecretStore();

      expect(getAuthEntry("counted")).toBeUndefined();
      expect(getAuthEntry("counted")).toBeUndefined();
      expect(getTestAuthSecretStoreReadCount()).toBe(2);

      resetAuthEntryCache();
      expect(getTestAuthSecretStoreReadCount()).toBe(2);

      resetTestAuthSecretStore();
      expect(getTestAuthSecretStoreReadCount()).toBe(0);
    }
    process.env[STORE_ENV] = "memory";
  });

  it("counts throwing reads for unavailable and key-revoked stores", () => {
    const recoveryBefore = process.env[DISABLE_KEYRING_RECOVERY_ENV];
    process.env[DISABLE_KEYRING_RECOVERY_ENV] = "1";
    for (const store of ["unavailable", "keyrevoked"]) {
      process.env[STORE_ENV] = store;
      resetTestAuthSecretStore();

      expect(() => getAuthEntry("counted")).toThrow();
      expect(getTestAuthSecretStoreReadCount()).toBe(1);
    }
    if (recoveryBefore === undefined) delete process.env[DISABLE_KEYRING_RECOVERY_ENV];
    else process.env[DISABLE_KEYRING_RECOVERY_ENV] = recoveryBefore;
    process.env[STORE_ENV] = "memory";
  });

  it("opts in independently of Linux keyring recovery", () => {
    const recoveryBefore = process.env[RECOVERY_OVERRIDE_ENV];
    enableAuthEntryCache();
    expect(process.env[DISABLE_ENV]).toBeUndefined();
    expect(process.env[RECOVERY_OVERRIDE_ENV]).toBe(recoveryBefore);
  });


  it("restores the suite-wide disable after an opt-in test", () => {
    expect(process.env[DISABLE_ENV]).toBe("1");
  });
});

describe("OAuth credential-entry cache — coherence", () => {
  useAuthCacheHarness();

  it("caches present and absent reads", () => {
    saveAuthEntry("present", { tokens: { accessToken: "a" } }, SERVER_URL);
    enableAuthEntryCache();
    resetAuthEntryCache();
    const before = getTestAuthSecretStoreReadCount();
    expect(getAuthEntry("present")?.tokens?.accessToken).toBe("a");
    expect(getAuthEntry("present")?.tokens?.accessToken).toBe("a");
    expect(getTestAuthSecretStoreReadCount() - before).toBe(1);

    const absentBefore = getTestAuthSecretStoreReadCount();
    expect(getAuthEntry("absent")).toBeUndefined();
    expect(getAuthEntry("absent")).toBeUndefined();
    expect(getTestAuthSecretStoreReadCount() - absentBefore).toBe(1);
  });

  it("publishes writes, updates, and evicts removals", () => {
    enableAuthEntryCache();
    saveAuthEntry("entry", { tokens: { accessToken: "old" } }, SERVER_URL);
    const before = getTestAuthSecretStoreReadCount();
    expect(getAuthEntry("entry")?.tokens?.accessToken).toBe("old");
    expect(getTestAuthSecretStoreReadCount() - before).toBe(0);
    updateTokens("entry", { accessToken: "new" }, SERVER_URL);
    expect(getAuthEntry("entry")?.tokens?.accessToken).toBe("new");
    removeAuthEntry("entry");
    const beforeAbsentRead = getTestAuthSecretStoreReadCount();
    expect(getAuthEntry("entry")).toBeUndefined();
    expect(getTestAuthSecretStoreReadCount() - beforeAbsentRead).toBeGreaterThan(0);
  });

  it("isolates nested mutations and bypasses status inspection", () => {
    saveAuthEntry("aliased", {
      tokens: { accessToken: "a" },
      clientInfo: { clientId: "c", redirectUris: ["https://a.example"] },
    }, SERVER_URL);
    enableAuthEntryCache();
    resetAuthEntryCache();
    const entry = getAuthEntry("aliased")!;
    entry.tokens!.issuer = "https://evil.example";
    entry.clientInfo!.redirectUris!.push("https://evil.example");
    const onHit = getAuthEntry("aliased")!;
    expect(onHit.tokens?.issuer).toBeUndefined();
    expect(onHit.clientInfo?.redirectUris).toEqual(["https://a.example"]);
    onHit.tokens!.issuer = "https://also-evil.example";
    expect(getAuthEntry("aliased")?.tokens?.issuer).toBeUndefined();

    resetAuthEntryCache();
    const before = getTestAuthSecretStoreReadCount();
    inspectAuthForUrl("aliased", SERVER_URL);
    inspectAuthForUrl("aliased", SERVER_URL);
    expect(getTestAuthSecretStoreReadCount() - before).toBe(2);

    const beforeOrdinaryRead = getTestAuthSecretStoreReadCount();
    expect(getAuthEntry("aliased")).toBeDefined();
    expect(getTestAuthSecretStoreReadCount() - beforeOrdinaryRead).toBe(1);
  });


  it("keeps inspection uncached after an ordinary read warms the cache", () => {
    saveAuthEntry("inspected", { tokens: { accessToken: "a" } }, SERVER_URL);
    enableAuthEntryCache();
    resetAuthEntryCache();

    expect(getAuthEntry("inspected")).toBeDefined();
    const before = getTestAuthSecretStoreReadCount();

    expect(inspectAuthForUrl("inspected", SERVER_URL).status).toBe("present");
    expect(getTestAuthSecretStoreReadCount() - before).toBe(1);
  });

  it("does not cache store failures and reconstructs chunked entries once", () => {
    enableAuthEntryCache();
    process.env[STORE_ENV] = "unavailable";
    expect(() => getAuthEntry("failing")).toThrow(/OS secure credential store/);
    expect(() => getAuthEntry("failing")).toThrow(/OS secure credential store/);
    process.env[STORE_ENV] = "memory";
    expect(getAuthEntry("failing")).toBeUndefined();

    saveAuthEntry("chunked", { tokens: { accessToken: "x".repeat(5000) } }, SERVER_URL);
    resetAuthEntryCache();
    getAuthEntry("chunked");
    const afterFirst = getTestAuthSecretStoreReadCount();
    expect(getAuthEntry("chunked")?.tokens?.accessToken).toHaveLength(5000);
    expect(getTestAuthSecretStoreReadCount()).toBe(afterFirst);
  });

  it("does not cache a failed conversion and caches only after compaction succeeds", () => {
    if (process.platform === "win32") return;
    process.env[STORE_ENV] = "sizelimited";
    const token = "x".repeat(5000);
    saveAuthEntry("conversion-cache", { tokens: { accessToken: token } }, SERVER_URL);
    enableAuthEntryCache();
    resetAuthEntryCache();

    process.env[STORE_ENV] = "memory";
    expect(inspectAuthForUrl("conversion-cache", SERVER_URL).status).toBe("present");
    expect(getTestAuthSecretStoreEntries().some(([account]) => account.includes(".chunk."))).toBe(true);

    process.env[STORE_ENV] = "writefailing";
    const beforeFailures = getTestAuthSecretStoreReadCount();
    expect(() => getAuthEntry("conversion-cache")).toThrow(/write OAuth credentials/);
    expect(() => getAuthEntry("conversion-cache")).toThrow(/write OAuth credentials/);
    expect(getTestAuthSecretStoreReadCount() - beforeFailures).toBeGreaterThan(2);
    expect(getTestAuthSecretStoreEntries().some(([account]) => account.includes(".chunk."))).toBe(true);

    process.env[STORE_ENV] = "memory";
    expect(getAuthEntry("conversion-cache")?.tokens?.accessToken).toBe(token);
    expect(getTestAuthSecretStoreEntries()).toHaveLength(1);
    const afterSuccess = getTestAuthSecretStoreReadCount();
    expect(getAuthEntry("conversion-cache")?.tokens?.accessToken).toBe(token);
    expect(getTestAuthSecretStoreReadCount()).toBe(afterSuccess);
  });


  it("leaves every read going to the store when the gate is off", () => {
    saveAuthEntry("gated", { tokens: { accessToken: "a" } }, SERVER_URL);
    const before = getTestAuthSecretStoreReadCount();

    expect(getAuthEntry("gated")).toBeDefined();
    expect(getAuthEntry("gated")).toBeDefined();

    expect(getTestAuthSecretStoreReadCount() - before).toBe(2);
  });

  it("normalizes publication exactly as a later store reload does", () => {
    enableAuthEntryCache();
    saveAuthEntry("normalized", {
      tokens: { accessToken: "a", unexpected: "discard" },
      unexpected: true,
    } as unknown as AuthEntry, SERVER_URL);

    const onHit = getAuthEntry("normalized");
    resetAuthEntryCache();
    const onMiss = getAuthEntry("normalized");

    expect(onHit).toEqual({ tokens: { accessToken: "a" }, serverUrl: SERVER_URL });
    expect(onMiss).toEqual(onHit);
  });
});

describe("OAuth credential-entry cache — invalidation", () => {
  useAuthCacheHarness();

  function writeBehindTheCache(serverName: string, accessToken: string): void {
    process.env[DISABLE_ENV] = "1";
    saveAuthEntry(serverName, { tokens: { accessToken } }, SERVER_URL);
    delete process.env[DISABLE_ENV];
  }

  it("reloads externally changed, absent, and chunked credentials", () => {
    enableAuthEntryCache();
    saveAuthEntry("rotated", { tokens: { accessToken: "old" } }, SERVER_URL);
    writeBehindTheCache("rotated", "new");
    expect(getAuthEntry("rotated")?.tokens?.accessToken).toBe("old");
    invalidateAuthEntryCache("rotated");
    expect(getAuthEntry("rotated")?.tokens?.accessToken).toBe("new");

    expect(getAuthEntry("appearing")).toBeUndefined();
    writeBehindTheCache("appearing", "created");
    expect(getAuthEntry("appearing")).toBeUndefined();
    invalidateAuthEntryCache("appearing");
    expect(getAuthEntry("appearing")?.tokens?.accessToken).toBe("created");

    process.env[STORE_ENV] = "sizelimited";
    const token = "x".repeat(5000);
    saveAuthEntry("chunked", { tokens: { accessToken: token } }, SERVER_URL);
    invalidateAuthEntryCache("chunked");
    const before = getTestAuthSecretStoreReadCount();
    expect(getAuthEntry("chunked")?.tokens?.accessToken).toBe(token);
    expect(getTestAuthSecretStoreReadCount() - before).toBeGreaterThan(1);
  });

  it("only evicts its target and is harmless while disabled", () => {
    enableAuthEntryCache();
    saveAuthEntry("keep", { tokens: { accessToken: "k" } }, SERVER_URL);
    saveAuthEntry("drop", { tokens: { accessToken: "d" } }, SERVER_URL);
    invalidateAuthEntryCache("drop");
    const before = getTestAuthSecretStoreReadCount();
    expect(getAuthEntry("keep")?.tokens?.accessToken).toBe("k");
    expect(getTestAuthSecretStoreReadCount() - before).toBe(0);

    process.env[DISABLE_ENV] = "1";
    expect(() => invalidateAuthEntryCache("keep")).not.toThrow();
    const beforeDisabledRead = getTestAuthSecretStoreReadCount();
    expect(getAuthEntry("keep")?.tokens?.accessToken).toBe("k");
    expect(getTestAuthSecretStoreReadCount() - beforeDisabledRead).toBe(1);
  });


  it("evicts a removed credential even when the gate is turned off", () => {
    enableAuthEntryCache();
    saveAuthEntry("toggled", { tokens: { accessToken: "t" } }, SERVER_URL);
    expect(getAuthEntry("toggled")).toBeDefined();

    process.env[DISABLE_ENV] = "1";
    removeAuthEntry("toggled");
    delete process.env[DISABLE_ENV];

    expect(getAuthEntry("toggled")).toBeUndefined();
  });
});

import { describe, expect, it } from "vitest";
import { canonicalMcpServerUrl, normalizeMcpInstallRequest } from "../mcp-install.ts";

describe("single-URL MCP installation", () => {
  it("normalizes HTTPS endpoints and derives a stable server name", () => {
    expect(normalizeMcpInstallRequest({ url: " https://forex-dev.1above.io/mcp " })).toEqual({
      url: "https://forex-dev.1above.io/mcp",
      serverName: "forex-dev",
    });
  });

  it("accepts an explicit safe server name", () => {
    expect(normalizeMcpInstallRequest({
      url: "https://forex-dev.1above.io/mcp",
      serverName: "forex",
    }).serverName).toBe("forex");
  });

  it("allows loopback HTTP without allowing remote plaintext HTTP", () => {
    expect(normalizeMcpInstallRequest({ url: "http://127.0.0.1:3000/mcp" }).serverName).toBe("local-mcp");
    expect(() => normalizeMcpInstallRequest({ url: "http://example.com/mcp" })).toThrow("must use HTTPS");
  });

  it.each([
    "https://user:secret@example.com/mcp",
    "https://example.com/mcp#token",
    "file:///tmp/mcp.sock",
  ])("rejects unsafe endpoint %s", (url) => {
    expect(() => normalizeMcpInstallRequest({ url })).toThrow();
  });

  it("rejects unsafe explicit names", () => {
    expect(() => normalizeMcpInstallRequest({
      url: "https://example.com/mcp",
      serverName: "../../server",
    })).toThrow("server name");
  });

  it("canonicalizes comparable existing URLs", () => {
    expect(canonicalMcpServerUrl("https://example.com")).toBe("https://example.com/");
    expect(canonicalMcpServerUrl("not a URL")).toBeUndefined();
  });
});

/**
 * Tests for the public OAuth token reuse API.
 */

import { describe, it, beforeEach } from "node:test";
import assert from "node:assert";

process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "memory";

const {
  getMcpOAuthTokensForUrl,
  inspectMcpOAuthTokensForUrl,
  updateMcpOAuthTokensForUrl,
} = await import("pi-mcp-adapter/oauth");
const {
  getAuthForUrl,
  resetTestAuthSecretStore,
  saveAuthEntry,
} = await import("./mcp-auth.ts");

describe("public OAuth token API", () => {
  beforeEach(() => {
    resetTestAuthSecretStore();
  });

  it("reads and updates URL-bound tokens through the package export", async () => {
    const expiresAt = Date.now() / 1000 + 3600;
    await updateMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp", {
      accessToken: "access-1",
      refreshToken: "refresh-1",
      expiresAt,
      scope: "read write",
    });

    assert.deepStrictEqual(await getMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp"), {
      accessToken: "access-1",
      refreshToken: "refresh-1",
      expiresAt,
      scope: "read write",
    });
    assert.deepStrictEqual(inspectMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp"), {
      status: "present",
      tokens: {
        accessToken: "access-1",
        refreshToken: "refresh-1",
        expiresAt,
        scope: "read write",
      },
    });
  });

  it("does not return tokens for a different URL", async () => {
    await updateMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp", { accessToken: "access-1" });

    assert.strictEqual(await getMcpOAuthTokensForUrl("jira", "https://other.example.com/mcp"), undefined);
    assert.deepStrictEqual(inspectMcpOAuthTokensForUrl("jira", "https://other.example.com/mcp"), {
      status: "absent",
    });
  });

  it("uses one token snapshot for expiry and return decisions", async () => {
    const serverUrl = "https://jira.example.com/mcp";
    await updateMcpOAuthTokensForUrl("jira", serverUrl, {
      accessToken: "expired-access",
      refreshToken: "refresh-1",
      expiresAt: Date.now() / 1000 - 60,
    });

    const pending = getMcpOAuthTokensForUrl("jira", serverUrl);
    await updateMcpOAuthTokensForUrl("jira", serverUrl, {
      accessToken: "current-access",
      expiresAt: Date.now() / 1000 + 3600,
    });

    assert.strictEqual(await pending, undefined);
    assert.strictEqual((await getMcpOAuthTokensForUrl("jira", serverUrl))?.accessToken, "current-access");
  });

  it("does not expose client info or OAuth flow secrets", () => {
    saveAuthEntry("jira", {
      tokens: { accessToken: "access-1" },
      clientInfo: { clientId: "client-1", clientSecret: "secret-1" },
      codeVerifier: "verifier-1",
      oauthState: "state-1",
      serverUrl: "https://jira.example.com/mcp",
    }, "https://jira.example.com/mcp");

    const status = inspectMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp");
    assert.deepStrictEqual(status, { status: "present", tokens: { accessToken: "access-1" } });
    assert(!("entry" in status));
  });

  it("does not return refreshable expired tokens as valid when refresh cannot complete", async () => {
    const expiresAt = Date.now() / 1000 - 3600;
    saveAuthEntry("jira", {
      tokens: {
        accessToken: "expired-token",
        refreshToken: "refresh-token",
        expiresAt,
      },
      clientInfo: { clientId: "config-client", configPreRegistered: true },
      serverUrl: "https://jira.example.com/mcp",
    }, "https://jira.example.com/mcp");

    assert.strictEqual(await getMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp"), undefined);
    assert.deepStrictEqual(inspectMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp"), {
      status: "present",
      tokens: {
        accessToken: "expired-token",
        refreshToken: "refresh-token",
        expiresAt,
      },
    });
  });

  it("fails closed when the secure credential store is unavailable", async () => {
    const previous = process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE;
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "unavailable";
    resetTestAuthSecretStore();
    try {
      await assert.rejects(
        () => getMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp"),
        /Failed to read OAuth credentials.*OS secure credential store/,
      );
      let updatePromise!: Promise<void>;
      assert.doesNotThrow(() => {
        updatePromise = updateMcpOAuthTokensForUrl(
          "jira",
          "https://jira.example.com/mcp",
          { accessToken: "access-1" },
        );
      });
      assert(updatePromise instanceof Promise);
      await assert.rejects(updatePromise, /Failed to read OAuth credentials.*OS secure credential store/);
      const status = inspectMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp");
      assert.strictEqual(status.status, "unavailable");
    } finally {
      if (previous === undefined) {
        delete process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE;
      } else {
        process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = previous;
      }
      resetTestAuthSecretStore();
    }
  });

  it("clears stale URL-bound state when tokens move to another URL", async () => {
    saveAuthEntry("jira", {
      tokens: { accessToken: "old-token" },
      clientInfo: { clientId: "old-client" },
      codeVerifier: "old-verifier",
      oauthState: "old-state",
      serverUrl: "https://old.example.com/mcp",
    }, "https://old.example.com/mcp");

    await updateMcpOAuthTokensForUrl("jira", "https://new.example.com/mcp", { accessToken: "new-token" });

    assert.strictEqual(await getMcpOAuthTokensForUrl("jira", "https://old.example.com/mcp"), undefined);
    assert.deepStrictEqual(await getMcpOAuthTokensForUrl("jira", "https://new.example.com/mcp"), {
      accessToken: "new-token",
    });
    const privateEntry = getAuthForUrl("jira", "https://new.example.com/mcp");
    assert.strictEqual(privateEntry?.clientInfo, undefined);
    assert.strictEqual(privateEntry?.codeVerifier, undefined);
    assert.strictEqual(privateEntry?.oauthState, undefined);
  });
});

import assert from "node:assert"
import { createHash } from "node:crypto"
import { createServer } from "node:http"
import { after, before, describe, it } from "node:test"

import {
  authenticate,
  completeAuth,
  initializeOAuth,
  shutdownOAuth,
  startAuth,
} from "./mcp-auth-flow.ts"
import {
  clearAllCredentials,
  getAuthForUrl,
  getTestAuthSecretStoreEntries,
  resetTestAuthSecretStore,
  updateClientInfo,
  updateTokens,
} from "./mcp-auth.ts"
import { waitForCallback } from "./mcp-callback-server.ts"

describe("local OAuth authorization-code flow", () => {
  const serverName = "local-oauth-integration"
  let origin = ""
  let serverUrl = ""
  let authorizationRequest: URL | undefined
  let tokenRequest: URLSearchParams | undefined
  const registrationRedirectUris: string[][] = []
  const refreshTokenRequests: URLSearchParams[] = []
  const authServer = createServer(async (request, response) => {
    const requestUrl = new URL(request.url ?? "/", origin || "http://127.0.0.1")

    if (request.method === "POST" && requestUrl.pathname === "/mcp") {
      response.writeHead(401, {
        "WWW-Authenticate": `Bearer resource_metadata="${origin}/.well-known/oauth-protected-resource"`,
      })
      response.end()
      return
    }

    if (request.method === "GET" && requestUrl.pathname === "/.well-known/oauth-protected-resource") {
      response.writeHead(200, { "Content-Type": "application/json" })
      response.end(JSON.stringify({
        resource: serverUrl,
        authorization_servers: [origin],
        scopes_supported: ["mcp:read"],
      }))
      return
    }

    if (request.method === "GET" && [
      "/.well-known/oauth-authorization-server",
      "/.well-known/openid-configuration",
    ].includes(requestUrl.pathname)) {
      response.writeHead(200, { "Content-Type": "application/json" })
      response.end(JSON.stringify({
        issuer: origin,
        authorization_endpoint: `${origin}/authorize`,
        token_endpoint: `${origin}/token`,
        registration_endpoint: `${origin}/register`,
        response_types_supported: ["code"],
        code_challenge_methods_supported: ["S256"],
        token_endpoint_auth_methods_supported: ["none"],
        authorization_response_iss_parameter_supported: true,
      }))
      return
    }

    if (request.method === "POST" && requestUrl.pathname === "/register") {
      let body = ""
      for await (const chunk of request) body += chunk
      const metadata = JSON.parse(body) as { redirect_uris?: string[] }
      const redirectUris = metadata.redirect_uris ?? []
      registrationRedirectUris.push(redirectUris)
      response.writeHead(201, { "Content-Type": "application/json" })
      response.end(JSON.stringify({
        client_id: "new-dynamic-client",
        redirect_uris: redirectUris,
      }))
      return
    }

    if (request.method === "POST" && requestUrl.pathname === "/token") {
      let body = ""
      for await (const chunk of request) body += chunk
      tokenRequest = new URLSearchParams(body)
      if (tokenRequest.get("grant_type") === "refresh_token"
        && tokenRequest.get("refresh_token") === "revoked-refresh") {
        refreshTokenRequests.push(tokenRequest)
        response.writeHead(400, { "Content-Type": "application/json" })
        response.end(JSON.stringify({ error: "invalid_grant" }))
        return
      }
      response.writeHead(200, { "Content-Type": "application/json" })
      response.end(JSON.stringify({
        access_token: "example-access-token",
        refresh_token: "example-refresh-token",
        token_type: "Bearer",
        expires_in: 900,
        scope: "mcp:read",
      }))
      return
    }

    response.writeHead(404)
    response.end()
  })

  before(async () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "memory"
    process.env.PI_MCP_ADAPTER_DISABLE_AUTH_CACHE = "1"
    resetTestAuthSecretStore()
    await new Promise<void>((resolve, reject) => {
      authServer.once("error", reject)
      authServer.listen(0, "127.0.0.1", resolve)
    })
    const address = authServer.address()
    if (!address || typeof address === "string") throw new Error("OAuth test server did not bind a TCP port")
    origin = `http://127.0.0.1:${address.port}`
    serverUrl = `${origin}/mcp`
    await initializeOAuth()
  })

  after(async () => {
    await shutdownOAuth()
    clearAllCredentials(serverName)
    resetTestAuthSecretStore()
    await new Promise<void>(resolve => authServer.close(() => resolve()))
  })

  it("authorizes with S256 PKCE, handles a dynamic loopback callback, and stores tokens securely", async () => {
    const { authorizationUrl } = await startAuth(serverName, serverUrl, {
      url: serverUrl,
      auth: "oauth",
      oauth: {
        clientId: "pi-dev-client",
        scope: "mcp:read",
        redirectUri: "http://127.0.0.1:{port}/callback",
      },
    })
    authorizationRequest = new URL(authorizationUrl)

    assert.strictEqual(authorizationRequest.pathname, "/authorize")
    assert.strictEqual(authorizationRequest.searchParams.get("client_id"), "pi-dev-client")
    assert.strictEqual(authorizationRequest.searchParams.get("code_challenge_method"), "S256")
    assert.strictEqual(authorizationRequest.searchParams.get("resource"), serverUrl)
    assert.strictEqual(authorizationRequest.searchParams.get("scope"), "mcp:read")

    const state = authorizationRequest.searchParams.get("state")
    const redirectUri = authorizationRequest.searchParams.get("redirect_uri")
    const codeChallenge = authorizationRequest.searchParams.get("code_challenge")
    assert.ok(state)
    assert.match(redirectUri ?? "", /^http:\/\/127\.0\.0\.1:\d+\/callback$/)
    assert.ok(codeChallenge)

    const callbackResultPromise = waitForCallback(state)
    const callbackUrl = new URL(redirectUri!)
    callbackUrl.searchParams.set("code", "example-authorization-code")
    callbackUrl.searchParams.set("state", state)
    callbackUrl.searchParams.set("iss", origin)
    const callbackResponse = await fetch(callbackUrl)
    assert.strictEqual(callbackResponse.status, 200)

    const callbackResult = await callbackResultPromise
    assert.deepStrictEqual(callbackResult, {
      code: "example-authorization-code",
      iss: origin,
    })
    assert.strictEqual(await completeAuth(serverName, callbackResult), "authenticated")

    assert.strictEqual(tokenRequest?.get("grant_type"), "authorization_code")
    assert.strictEqual(tokenRequest?.get("code"), "example-authorization-code")
    assert.strictEqual(tokenRequest?.get("client_id"), "pi-dev-client")
    assert.strictEqual(tokenRequest?.get("redirect_uri"), redirectUri)
    assert.strictEqual(tokenRequest?.get("resource"), serverUrl)
    const codeVerifier = tokenRequest?.get("code_verifier")
    assert.ok(codeVerifier)
    assert.strictEqual(
      createHash("sha256").update(codeVerifier).digest("base64url"),
      codeChallenge,
    )

    const stored = await getAuthForUrl(serverName, serverUrl)
    assert.strictEqual(stored?.tokens?.accessToken, "example-access-token")
    assert.strictEqual(stored?.tokens?.refreshToken, "example-refresh-token")
    assert.strictEqual(stored?.tokens?.scope, "mcp:read")
    assert.strictEqual(stored?.clientInfo?.clientId, "pi-dev-client")
    assert.strictEqual(stored?.codeVerifier, undefined)
    assert.strictEqual(stored?.oauthState, undefined)

    const secureStorePayload = getTestAuthSecretStoreEntries().map(([, value]) => value).join("")
    assert.ok(secureStorePayload.includes("example-access-token"))
    assert.ok(secureStorePayload.includes("example-refresh-token"))
    assert.ok(!secureStorePayload.includes(codeVerifier))
    assert.ok(!secureStorePayload.includes(state))
  })

  it("opens the authorization URL and completes from the watched loopback callback", async () => {
    const watchedServerName = `${serverName}-watched`
    let openedAuthorizationUrl: string | undefined

    try {
      const status = await authenticate(watchedServerName, serverUrl, {
        url: serverUrl,
        auth: "oauth",
        oauth: { redirectUri: "http://127.0.0.1:{port}/callback", scope: "mcp:read" },
      }, {
        openAuthorizationUrl: async (authorizationUrl) => {
          openedAuthorizationUrl = authorizationUrl
          const authorizationRequest = new URL(authorizationUrl)
          const callbackUrl = new URL(authorizationRequest.searchParams.get("redirect_uri")!)
          callbackUrl.searchParams.set("code", "watched-authorization-code")
          callbackUrl.searchParams.set("state", authorizationRequest.searchParams.get("state")!)
          callbackUrl.searchParams.set("iss", origin)
          const response = await fetch(callbackUrl)
          assert.strictEqual(response.status, 200)
        },
      })

      assert.strictEqual(status, "authenticated")
      assert.ok(openedAuthorizationUrl)
      assert.strictEqual(tokenRequest?.get("code"), "watched-authorization-code")
    } finally {
      clearAllCredentials(watchedServerName)
    }
  })

  it("re-registers a stale dynamic client after a refresh invalid_grant", async () => {
    const refreshServerName = "local-oauth-redirect-refresh"
    const staleRedirectUri = "http://127.0.0.1:1/callback"
    await updateClientInfo(refreshServerName, {
      clientId: "stale-dynamic-client",
      redirectUris: [staleRedirectUri],
    }, serverUrl)
    await updateTokens(refreshServerName, {
      accessToken: "expired-access-token",
      refreshToken: "revoked-refresh",
      expiresAt: Date.now() / 1000 - 60,
    }, serverUrl)

    const registrationCount = registrationRedirectUris.length
    refreshTokenRequests.length = 0
    const { authorizationUrl } = await startAuth(refreshServerName, serverUrl, {
      url: serverUrl,
      auth: "oauth",
      oauth: { redirectUri: "http://127.0.0.1:{port}/callback" },
    })
    const fallbackAuthorizationRequest = new URL(authorizationUrl)

    assert.strictEqual(refreshTokenRequests.length, 1)
    assert.strictEqual(registrationRedirectUris.length, registrationCount + 1)
    const registeredRedirectUri = registrationRedirectUris[registrationRedirectUris.length - 1]?.[0]
    assert.ok(registeredRedirectUri)
    assert.notStrictEqual(registeredRedirectUri, staleRedirectUri)
    assert.strictEqual(fallbackAuthorizationRequest.searchParams.get("client_id"), "new-dynamic-client")
    assert.strictEqual(
      fallbackAuthorizationRequest.searchParams.get("redirect_uri"),
      registeredRedirectUri,
    )

    const stored = await getAuthForUrl(refreshServerName, serverUrl)
    assert.strictEqual(stored?.clientInfo?.clientId, "new-dynamic-client")
    clearAllCredentials(refreshServerName)
  })
})

import assert from "node:assert"
import { createServer } from "node:http"
import { after, before, describe, it } from "node:test"

import {
  initializeOAuth,
  shutdownOAuth,
  startAuth,
} from "./mcp-auth-flow.ts"
import {
  clearAllCredentials,
  resetTestAuthSecretStore,
} from "./mcp-auth.ts"

// A stalling authorization server proves the OAuth flow's outbound requests are
// timeout-bounded. Without the bound, the metadata fetch below would hang until
// the OS TCP timeout.
describe("OAuth flow request timeout", () => {
  const serverName = "oauth-timeout"
  let origin = ""
  let serverUrl = ""
  const previousTimeoutMs = process.env.PI_MCP_OAUTH_REQUEST_TIMEOUT_MS

  const server = createServer((request, response) => {
    const requestUrl = new URL(request.url ?? "/", origin || "http://127.0.0.1")

    if (request.method === "POST" && requestUrl.pathname === "/mcp") {
      response.writeHead(401, {
        "WWW-Authenticate": `Bearer resource_metadata="${origin}/.well-known/oauth-protected-resource"`,
      })
      response.end()
      return
    }

    if (request.method === "GET" && requestUrl.pathname === "/.well-known/oauth-protected-resource") {
      response.writeHead(200, { "Content-Type": "application/json" })
      response.end(JSON.stringify({
        resource: serverUrl,
        authorization_servers: [origin],
      }))
      return
    }

    // Authorization-server metadata never responds; this is the stall the flow
    // must not wait on.
    if (request.method === "GET" && [
      "/.well-known/oauth-authorization-server",
      "/.well-known/openid-configuration",
    ].includes(requestUrl.pathname)) {
      return
    }

    response.writeHead(404)
    response.end()
  })

  before(async () => {
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "memory"
    process.env.PI_MCP_ADAPTER_DISABLE_AUTH_CACHE = "1"
    process.env.PI_MCP_OAUTH_REQUEST_TIMEOUT_MS = "200"
    resetTestAuthSecretStore()
    await new Promise<void>((resolve, reject) => {
      server.once("error", reject)
      server.listen(0, "127.0.0.1", resolve)
    })
    const address = server.address()
    if (!address || typeof address === "string") throw new Error("test server did not bind a TCP port")
    origin = `http://127.0.0.1:${address.port}`
    serverUrl = `${origin}/mcp`
    await initializeOAuth()
  })

  after(async () => {
    if (previousTimeoutMs === undefined) {
      delete process.env.PI_MCP_OAUTH_REQUEST_TIMEOUT_MS
    } else {
      process.env.PI_MCP_OAUTH_REQUEST_TIMEOUT_MS = previousTimeoutMs
    }
    await shutdownOAuth()
    clearAllCredentials(serverName)
    resetTestAuthSecretStore()
    await new Promise<void>(resolve => server.close(() => resolve()))
  })

  it("rejects when authorization-server metadata stalls, instead of hanging", async () => {
    const startedAt = Date.now()
    await assert.rejects(
      () => startAuth(serverName, serverUrl, { url: serverUrl, auth: "oauth" }),
    )
    const elapsedMs = Date.now() - startedAt
    assert.ok(
      elapsedMs < 5_000,
      `startAuth should have rejected at the request timeout, took ${elapsedMs}ms`,
    )
  })

  it("ignores malformed numeric-looking timeout overrides", async () => {
    process.env.PI_MCP_OAUTH_REQUEST_TIMEOUT_MS = "1e999"
    const originalTimeout = AbortSignal.timeout
    const observedTimeouts: number[] = []
    Object.defineProperty(AbortSignal, "timeout", {
      configurable: true,
      value(milliseconds: number) {
        observedTimeouts.push(milliseconds)
        return originalTimeout.call(AbortSignal, 50)
      },
    })

    try {
      await assert.rejects(
        () => startAuth(`${serverName}-malformed`, serverUrl, { url: serverUrl, auth: "oauth" }),
      )
    } finally {
      Object.defineProperty(AbortSignal, "timeout", {
        configurable: true,
        value: originalTimeout,
      })
      process.env.PI_MCP_OAUTH_REQUEST_TIMEOUT_MS = "200"
    }

    assert.equal(observedTimeouts[0], 30_000)
  })
})

import { visibleWidth } from "@earendil-works/pi-tui";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it, vi } from "vitest";
import { createMcpSetupPanel, type SetupPanelCallbacks } from "../mcp-setup-panel.ts";
import { KNOWN_SERVER_PRESETS, previewSharedServerEntry, type McpDiscoverySummary } from "../config.ts";
import { createTheme } from "./helpers/panel-theme.ts";

const DOWN = "\x1b[B";
const ENTER = "\r";

function stripAnsi(text: string): string {
  return text.replace(/\x1b\[[0-9;]*m/g, "");
}

function moveCursorTo(panel: { render(width: number): string[]; handleInput(data: string): void }, label: string): void {
  for (let presses = 0; presses < 40; presses += 1) {
    if (panel.render(200).some((line) => stripAnsi(line).includes(`› ${label}`))) return;
    panel.handleInput(DOWN);
  }
  throw new Error(`Setup cursor never reached ${label}`);
}

function createDiscovery(): McpDiscoverySummary {
  return {
    sources: [],
    imports: [],
    hostConfigs: [],
    hostConfigDiscovery: "off",
    agentPlugins: [],
    conflicts: [],
    hasAnyConfig: false,
    hasAnyDetectedPaths: false,
    hasSharedServers: false,
    hasPiOwnedServers: false,
    totalServerCount: 0,
    fingerprint: "test",
    repoPrompt: { configured: false },
    knownServerPresets: KNOWN_SERVER_PRESETS,
  };
}

function createCallbacks(): SetupPanelCallbacks {
  const preview = {
    path: "/tmp/mcp.json",
    existed: false,
    changed: true,
    beforeText: "",
    afterText: "",
    diffText: "",
  };
  return {
    previewImports: () => preview,
    previewStarterConfig: () => preview,
    previewRepoPrompt: () => null,
    previewKnownServer: () => preview,
    adoptImports: async () => ({ added: [], path: preview.path }),
    scaffoldConfig: async () => ({ path: preview.path }),
    addRepoPrompt: async () => ({ path: preview.path, serverName: "repoprompt" }),
    addKnownServer: async (preset) => ({ path: preview.path, serverName: preset.name }),
    openPath: async () => {},
    markSetupCompleted: () => {},
  };
}

describe("mcp setup panel theme and component rendering", () => {
  it("shows Tavily Search directly below Parallel Search in the add-server list", () => {
    const panel = createMcpSetupPanel(
      createDiscovery(),
      createCallbacks(),
      { mode: "setup", onboardingState: { version: 1, sharedConfigHintShown: false, setupCompleted: false } },
      { requestRender: () => {}, terminal: { rows: 60 } },
      () => {},
    );

    const lines = panel.render(200).map(stripAnsi);
    const parallelIndex = lines.findIndex((line) => line.includes("Parallel Search"));
    expect(parallelIndex).toBeGreaterThanOrEqual(0);
    expect(lines[parallelIndex + 1]).toContain("Tavily Search");
