      token_type: "Bearer",
      issuer: "https://auth.example.com",
    });
    expect(await provider.discoveryState()).toBeUndefined();

    await provider.saveDiscoveryState(discoveryState);
    await provider.invalidateCredentials("discovery");

    expect(await provider.discoveryState()).toBeUndefined();
    expect((await provider.tokens())?.access_token).toBe("access-token");
  });
});

describe("McpOAuthProvider authorization fallback", () => {
  const originalOAuthDir = process.env.MCP_OAUTH_DIR;
  const serverUrl = "https://api.example.com/mcp";
  let authDir: string;

  beforeEach(() => {
    authDir = mkdtempSync(join(tmpdir(), "pi-mcp-oauth-provider-"));
    process.env.MCP_OAUTH_DIR = authDir;
  });

  afterEach(() => {
    rmSync(authDir, { recursive: true, force: true });
    if (originalOAuthDir === undefined) {
      delete process.env.MCP_OAUTH_DIR;
    } else {
      process.env.MCP_OAUTH_DIR = originalOAuthDir;
    }
  });

  it("throws UnauthorizedError when state is requested outside a user-initiated flow", async () => {
    const provider = new McpOAuthProvider("state-missing", serverUrl, {}, { onRedirect: async () => {} });

    await expect(provider.state()).rejects.toBeInstanceOf(UnauthorizedError);
    await expect(provider.state()).rejects.toThrow(/Re-authentication required/);
  });

  it("throws UnauthorizedError before redirecting when no OAuth flow is in progress", async () => {
    let redirected = false;
    const provider = new McpOAuthProvider("redirect-missing", serverUrl, {}, {
      onRedirect: async () => {
        redirected = true;
      },
    });

    await expect(provider.redirectToAuthorization(new URL("https://auth.example.com/authorize")))
      .rejects.toBeInstanceOf(UnauthorizedError);
    expect(redirected).toBe(false);
  });

  it("redirects when the active provider owns OAuth state", async () => {
    const authUrl = new URL("https://auth.example.com/authorize");
    let redirected: URL | undefined;
    const provider = new McpOAuthProvider("redirect-active", serverUrl, {}, {
      onRedirect: async (url) => {
        redirected = url;
      },
    }, {}, undefined, "state-abc");

    await provider.redirectToAuthorization(authUrl);

    expect(redirected).toBe(authUrl);
  });

  it("throws before redirecting when only stale URL-bound state exists", async () => {
    let redirected = false;
    saveAuthEntry("redirect-stale-url", {
      oauthState: "state-abc",
      serverUrl: "https://old.example.com/mcp",
    }, "https://old.example.com/mcp");
    const provider = new McpOAuthProvider("redirect-stale-url", serverUrl, {}, {
      onRedirect: async () => {
        redirected = true;
      },
    });

    await expect(provider.redirectToAuthorization(new URL("https://auth.example.com/authorize")))
      .rejects.toBeInstanceOf(UnauthorizedError);
    expect(redirected).toBe(false);
  });
});

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  getAuthEntry, inspectAuthForUrl, OAuthCredentialStoreError, removeAuthEntry,
  resetTestAuthSecretStore, saveAuthEntry, setTestKeyringEntryClass,
} from "../mcp-auth.ts";

const url = "https://example.com/mcp";
const payload = (token: string) => JSON.stringify({ tokens: { accessToken: token }, serverUrl: url });

describe("OAuth native keyring Entry reuse", () => {
  const backing = new Map<string, string>();
  const constructed: FakeEntry[] = [];
  let freshReadError: Error | undefined;
  let freshFailureAfter = Infinity;
  let dir: string;
  const original = {
    store: process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE,
    cache: process.env.PI_MCP_ADAPTER_DISABLE_AUTH_CACHE,
    agentDir: process.env.PI_CODING_AGENT_DIR,
  };

  class FakeEntry {
    failRead = false;
    constructor(readonly service: string, readonly account: string) {
      constructed.push(this);
    }
    getPassword(): string | null {
      if (freshReadError && constructed.indexOf(this) >= freshFailureAfter) throw freshReadError;
      if (this.failRead) throw new Error("stale entry");
      return backing.get(this.account) ?? null;
    }
    setPassword(value: string): void { backing.set(this.account, value); }
    deleteCredential(): boolean { return backing.delete(this.account); }
  }

  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), "pi-mcp-oauth-entry-"));
    delete process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE;
    process.env.PI_MCP_ADAPTER_DISABLE_AUTH_CACHE = "1";
    process.env.PI_CODING_AGENT_DIR = dir;
    backing.clear();
    constructed.length = 0;
    freshReadError = undefined;
    freshFailureAfter = Infinity;
    resetTestAuthSecretStore();
    setTestKeyringEntryClass(FakeEntry);
  });

  afterEach(() => {
    setTestKeyringEntryClass(undefined);
    resetTestAuthSecretStore();
    if (original.store === undefined) delete process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE;
    else process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = original.store;
    if (original.cache === undefined) delete process.env.PI_MCP_ADAPTER_DISABLE_AUTH_CACHE;
    else process.env.PI_MCP_ADAPTER_DISABLE_AUTH_CACHE = original.cache;
    if (original.agentDir === undefined) delete process.env.PI_CODING_AGENT_DIR;
    else process.env.PI_CODING_AGENT_DIR = original.agentDir;
    rmSync(dir, { recursive: true, force: true });
  });

  it("reuses a healthy Entry while re-reading externally changed backing values, including status reads", () => {
    saveAuthEntry("one", { tokens: { accessToken: "first" } }, url);
    const entry = constructed.at(-1)!;
    expect(entry.service).toBe("pi-mcp-adapter.oauth");
    const count = constructed.length;
    expect(getAuthEntry("one")?.tokens?.accessToken).toBe("first");
    backing.set(entry.account, payload("external"));
    expect(getAuthEntry("one")?.tokens?.accessToken).toBe("external");
    expect(inspectAuthForUrl("one", url)).toMatchObject({ status: "present", entry: { tokens: { accessToken: "external" } } });
    expect(constructed).toHaveLength(count);
  });

  it("retries one stale cached read with a fresh Entry", () => {
    saveAuthEntry("one", { tokens: { accessToken: "first" } }, url);
    const stale = constructed.at(-1)!;
    backing.set(stale.account, payload("new"));
    stale.failRead = true;
    const count = constructed.length;
    expect(getAuthEntry("one")?.tokens?.accessToken).toBe("new");
    expect(constructed).toHaveLength(count + 1);
    expect(getAuthEntry("one")?.tokens?.accessToken).toBe("new");
    expect(constructed).toHaveLength(count + 1);
  });

  it("reports a fresh retry failure with the original auth error cause", () => {
    saveAuthEntry("one", { tokens: { accessToken: "first" } }, url);
    freshFailureAfter = constructed.length;
    freshReadError = new Error("fresh failure");
    // The stale instance must throw a different error from its replacement.
    const stale = constructed.at(-1)!;
    stale.failRead = true;
    let error: unknown;
    try { getAuthEntry("one"); } catch (caught) { error = caught; }
    expect(error).toBeInstanceOf(OAuthCredentialStoreError);
    expect((error as OAuthCredentialStoreError).cause).toBe(freshReadError);
    expect(constructed).toHaveLength(freshFailureAfter + 1);
    expect(inspectAuthForUrl("one", url).status).toBe("unavailable");
  });

  it("reuses a healthy missing Entry and observes a later external write", () => {
    expect(getAuthEntry("missing")).toBeUndefined();
    expect(constructed).toHaveLength(1);
    expect(getAuthEntry("missing")).toBeUndefined();
    expect(constructed).toHaveLength(1);
    const account = constructed.at(-1)!.account;
    backing.set(account, payload("external"));
    expect(getAuthEntry("missing")?.tokens?.accessToken).toBe("external");
    expect(constructed).toHaveLength(1);
  });

  it("invalidates on writes and removes, without retaining the remove Entry", () => {
    saveAuthEntry("one", { tokens: { accessToken: "first" } }, url);
    const first = constructed.at(-1)!;
    saveAuthEntry("one", { tokens: { accessToken: "second" } }, url);
    const second = constructed.at(-1)!;
    expect(second).not.toBe(first);
    const beforeRemove = constructed.length;
    removeAuthEntry("one");
    expect(constructed.length).toBeGreaterThan(beforeRemove);
    const afterRemove = constructed.length;
    expect(getAuthEntry("one")).toBeUndefined();
    expect(constructed.length).toBe(afterRemove + 1);
  });

  it("separates accounts and clears native Entries on test reset", () => {
    saveAuthEntry("one", { tokens: { accessToken: "one" } }, url);
    saveAuthEntry("two", { tokens: { accessToken: "two" } }, url);
    expect(constructed[0]!.account).not.toBe(constructed.at(-1)!.account);
    const count = constructed.length;
    getAuthEntry("one");
    getAuthEntry("two");
    expect(constructed).toHaveLength(count);
    resetTestAuthSecretStore();
    getAuthEntry("one");
    expect(constructed).toHaveLength(count + 1);
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { fileURLToPath } from "node:url";
import type { ExtensionMode, ExtensionUIContext } from "@earendil-works/pi-coding-agent";
import { createDirectToolExecutor } from "../direct-tools.ts";
import { isTuiMode } from "../init.ts";
import { executeCall } from "../proxy-modes.ts";
import { McpServerManager } from "../server-manager.ts";
import type { McpExtensionState } from "../state.ts";
import type { DirectToolSpec, ToolMetadata } from "../types.ts";
import { UiResourceHandler } from "../ui-resource-handler.ts";

const mocks = vi.hoisted(() => ({ open: vi.fn(async () => undefined) }));
vi.mock("open", () => ({ default: mocks.open }));

const fixture = fileURLToPath(new URL("./fixtures/elicitation-server.mjs", import.meta.url));
const definition = { command: process.execPath, args: [fixture] };
const managers: McpServerManager[] = [];

function createUi(answers: string[] = [], delayMs = 0): ExtensionUIContext {
  const later = async <T>(value: T) => {
    await new Promise(resolve => setTimeout(resolve, delayMs));
    return value;
  };
  return {
    select: vi.fn(async () => later(answers.shift())),
    input: vi.fn(async () => later("stock-pi-user")),
    notify: vi.fn(),
  } as unknown as ExtensionUIContext;
}

async function createConnectedManager(mode: ExtensionMode, answers: string[] = [], options: { callTimeoutMs?: number; answerDelayMs?: number } = {}) {
  const ui = createUi(answers, options.answerDelayMs);
  const manager = new McpServerManager();
  manager.setElicitationConfig({
    ui,
    allowUrl: isTuiMode({ hasUI: true, mode }),
  });
  await manager.connect("real", definition);
  // Set after connecting so a slow CI runner's spawn and handshake do not use up the call's timeout.
  manager.setDefaultRequestTimeoutMs(options.callTimeoutMs);
  managers.push(manager);
  return { manager, ui };
}

function createState(manager: McpServerManager, metadata: ToolMetadata[]): McpExtensionState {
  return {
    manager,
    config: { settings: {}, mcpServers: { real: definition } },
    toolMetadata: new Map([["real", metadata]]),
    serverInstructions: new Map(),
    failureTracker: new Map(),
    uiResourceHandler: new UiResourceHandler(manager),
    completedUiSessions: [],
    uiServer: null,
  } as McpExtensionState;
}

function resultText(result: { content?: Array<{ type: string; text?: string }> }): string {
  return result.content?.find(item => item.type === "text")?.text ?? "";
}

describe("elicitation with the real MCP SDK", () => {
  beforeEach(() => mocks.open.mockClear());

  afterEach(async () => {
    await Promise.all(managers.splice(0).map(manager => manager.closeAll()));
  });

  it.each([
    ["tui", { form: {}, url: {} }],
    ["rpc", { form: {} }],
  ] as const)("advertises stock Pi %s capabilities and completes form elicitation", async (mode, capabilities) => {
    const { manager } = await createConnectedManager(mode, ["Continue", "Enter value", "Submit"]);
    const connection = manager.getConnection("real")!;

    const capabilityResult = await connection.client.callTool({ name: "capabilities", arguments: {} });
    expect(JSON.parse(resultText(capabilityResult))).toEqual(capabilities);

    const formResult = await connection.client.callTool({ name: "form", arguments: {} });
    expect(JSON.parse(resultText(formResult))).toEqual({
      action: "accept",
      content: { name: "stock-pi-user" },
    });
  });

  const formSpec = { serverName: "real", prefixedName: "real_form", originalName: "form", description: "form" } as DirectToolSpec;

  it.each(["proxy", "direct"] as const)("does not count time spent answering a form against the %s call timeout", async (adapter) => {
    const { manager } = await createConnectedManager("tui", ["Continue", "Enter value", "Submit"], {
      callTimeoutMs: 500,
      answerDelayMs: 300,
    });
    const state = createState(manager, [{ name: "real_form", originalName: "form", description: "form" }]);

    const result = adapter === "proxy"
      ? await executeCall(state, "real_form", {}, "real")
      : await createDirectToolExecutor(() => state, () => null, formSpec)("id", {});

    expect(JSON.parse(resultText(result))).toEqual({ action: "accept", content: { name: "stock-pi-user" } });
  });

  it("cancels a call at once while its form is still open", async () => {
    const { manager, ui } = await createConnectedManager("tui", ["Continue"], { answerDelayMs: 30_000 });
    const state = createState(manager, [{ name: "real_form", originalName: "form", description: "form" }]);
    const controller = new AbortController();

    const call = createDirectToolExecutor(() => state, () => null, formSpec)("id", {}, controller.signal);
    await vi.waitFor(() => expect(ui.select).toHaveBeenCalled());
    controller.abort();

    await expect(call).resolves.toMatchObject({ details: { error: "aborted" } });
  });

  it("still times out a call that is not waiting on the user", async () => {
    const { manager } = await createConnectedManager("tui", [], { callTimeoutMs: 300 });
    const state = createState(manager, [{ name: "real_hang", originalName: "hang", description: "hang" }]);

    const result = await executeCall(state, "real_hang", {}, "real");

    expect(result.details).toMatchObject({ error: "call_failed", message: "Request timed out" });
  });

  it("rejects URL elicitation over real SDK dispatch in stock Pi RPC mode", async () => {
    const { manager } = await createConnectedManager("rpc");
    const connection = manager.getConnection("real")!;

    await expect(connection.client.callTool({ name: "url", arguments: {} })).rejects.toThrow(
      /does not support (?:URL-mode|url) elicitation/,
    );
    expect(mocks.open).not.toHaveBeenCalled();
  });

  it("dispatches URL elicitation and its completion notification over the real SDK", async () => {
    const { manager, ui } = await createConnectedManager("tui", ["Open"]);
    const connection = manager.getConnection("real")!;

    const result = await connection.client.callTool({ name: "url", arguments: {} });

    expect(JSON.parse(resultText(result))).toEqual({ action: "accept" });
    expect(mocks.open).toHaveBeenCalledWith("https://example.com/authorize");
    expect(ui.notify).toHaveBeenCalledWith(
      "MCP browser interaction for real completed. You can retry the tool now.",
      "info",
    );
    expect(ui.notify).toHaveBeenCalledTimes(2);
  });

  it.each([
    ["proxy tool", { originalName: "url-required" }, "proxy"],
    ["direct tool", { originalName: "url-required" }, "direct"],
    ["proxy resource", { originalName: "resource", resourceUri: "test://url-required" }, "proxy"],
    ["direct resource", { originalName: "resource", resourceUri: "test://url-required" }, "direct"],
    ["proxy UI resource", { originalName: "app", uiResourceUri: "ui://url-required" }, "proxy"],
    ["direct UI resource", { originalName: "app", uiResourceUri: "ui://url-required" }, "direct"],
  ] as const)("handles real -32042 errors from a %s", async (_label, spec, adapter) => {
    const { manager } = await createConnectedManager("tui", ["Open"]);
    const metadata: ToolMetadata = {
      name: `real_${spec.originalName}`,
      description: "integration test",
      ...spec,
    };
    const state = createState(manager, [metadata]);

    const result = adapter === "proxy"
      ? await executeCall(state, metadata.name, {}, "real")
      : await createDirectToolExecutor(
          () => state,
          () => null,
          {
            serverName: "real",
            prefixedName: metadata.name,
            description: metadata.description,
            ...spec,
          } as DirectToolSpec,
        )("id", {});

    expect(result.details).toMatchObject({ error: "url_elicitation_required", action: "accept" });
    expect(result.content[0]).toMatchObject({
      type: "text",
      text: expect.stringContaining("retry the tool"),
    });
    expect(mocks.open).toHaveBeenCalledWith("https://example.com/connect");
  });
});

